    for idx in 0..DIM {
        let delta = query[idx] as i32 - vector[idx] as i32;
        sum += (delta * delta) as u32;
    }

    sum
}

#[inline(always)]
fn l2_squared_u8_slice_scalar(query: &[u8], vector: &[u8]) -> u32 {
    let mut sum = 0u32;

    for idx in 0..query.len() {
        let delta = query[idx] as i32 - vector[idx] as i32;
        sum += (delta * delta) as u32;
