            }
            Err(err) if err.kind() == io::ErrorKind::UnexpectedEof => {
                if let Some(stats) = stats.as_ref() {
                    stats.flush_snapshot();
                }
                return Ok(());
            }
            Err(err) => return Err(err),
        };
