        let scope = std::env::var(ANN_COARSE_PRESCORE_SCOPE_ENV)
            .unwrap_or_else(|_| "cluster".to_string())
            .trim()
            .to_ascii_lowercase();
        match scope.as_str() {
            "primary" => Self::Primary,
            _ => Self::Cluster,
        }
    }
